import{z as n,x as l,o as B,c as d,q as o,j as i,D as r,d as a,s,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"随机数生成","description":"","frontmatter":{"title":"随机数生成","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sc-random-generation.md","filePath":"cs/sc-random-generation.md","lastUpdated":1791413859000}'),C={name:"cs/sc-random-generation.md"};function m(h,E,c,p,D,u){const A=l("Mermaid");return B(),d("div",null,[E[2]||(E[2]=o('<h1 id="随机数生成" tabindex="-1">随机数生成 <a class="header-anchor" href="#随机数生成" aria-label="Permalink to &quot;随机数生成&quot;">​</a></h1><div class="epigraph"><p>确定性机器上没有随机，只有长到看不出规律的确定性；生成器的合同是把规律藏过所有会用的检验。</p><footer>—— 据 Knuth, The Art of Computer Programming, Vol. 2；L&#39;Ecuyer and Simard, ACM TOMS, 2007 整理</footer></div><p><a href="/cs/sc-autodiff-implementation">上一课</a>在确定性程序里把导数算准；本课在确定性机器上造「独立同分布」。主干的<a href="/cs/randomized-algo">随机化算法直觉</a>与 <a href="/cs/las-vegas-monte-carlo">Las Vegas 与 Monte Carlo</a> 给过「为什么随机」，<a href="/cs/csprng">CSPRNG</a> 给过密码学的合同。缺口是科学计算那一份：周期、均匀性、并行流与可复现——蒙特卡洛把生成器的缺陷直接换算成估计量的偏差。后课默认随机源有名字、有种子、有流分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 库的 <code>rand()</code> 是 1960 年代的合同：周期短、状态暴露、<code>rand()%n</code> 有偏、跨库不可复现。蒙特卡洛用它，方差估计先错；并行模拟用它，各线程的流相关，样本互相抄袭。缺口是一份能挑选与验收的清单：按什么指标拒绝一个生成器，按什么方式给并行任务发流，按什么口径保证两个实验室算出同一条序列。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>生成器 = 状态转移加输出函数。经典线性族（LCG、MT19937）状态线性演化，周期可以极长——MT19937 达 \\(2^{19937}-1\\)（Matsumoto 与 Nishimura, 1998）——但结构线性：把连续输出叠成高维点，落在少数超平面上（Marsaglia, 1968），线性复杂度检验也抓得住它；TestU01 的 BigCrush 套件（L&#39;Ecuyer 与 Simard, 2007）是常用的验收线。现代修法是输出置换：PCG 与 xoshiro 在线性状态外再套一层非线性输出，状态小、速度快、过 BigCrush。第三族是计数器式（Philox、Threefry，Salmon et al., SC 2011）：第 \\(i\\) 个随机数就是计数器的哈希，没有状态演化——并行只需把计数器分段，天然可重放、可分块。整数区间用拒绝采样：先弃掉上界多余部分再取模。<span class="marginnote">「状态转移加输出函数」可以类比揉面与切片：状态是那团被不断揉的面（内部那串比特），输出函数是每回合从上面切下的一片。LCG 与 MT19937 的揉法是线性变换，懂线性代数的检验能倒推出面团；PCG 与 xoshiro 在外面多套一层非线性切片，倒推就难了。</span></p><p><span class="marginnote">模偏可以大到翻倍：32 位状态直接对 \\(n=3\\times10^9\\) 取模，\\(2^{32}\\bmod n\\approx 1.29\\times10^9\\)，于是余数 \\(0\\) 到 \\(1.29\\times10^9-1\\) 出现两次，其余只出现一次——一半的定义域概率是另一半的两倍。拒绝采样先丢掉 \\(\\bigl\\lfloor 2^{32}/n\\bigr\\rfloor n\\) 之上的尾巴，偏差归零。</span></p>',8)),(B(),i(t,null,{default:r(()=>[s(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E7%8A%B6%E6%80%81%E8%BD%AC%E7%A7%BB%22%5D%20--%3E%20OUT%5B%22%E8%BE%93%E5%87%BA%E5%87%BD%E6%95%B0%22%5D%0A%20%20OUT%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E6%97%8F%EF%BC%9A%E5%91%A8%E6%9C%9F%E9%95%BF%E4%BD%86%E7%BB%93%E6%9E%84%E7%BA%BF%E6%80%A7%22%5D%0A%20%20OUT%20--%3E%20PERM%5B%22%E7%BD%AE%E6%8D%A2%E8%BE%93%E5%87%BA%EF%BC%9APCG%20%E4%B8%8E%20xoshiro%22%5D%0A%20%20CNT%5B%22%E8%AE%A1%E6%95%B0%E5%99%A8%E5%BC%8F%EF%BC%9A%E7%AC%AC%20i%20%E4%B8%AA%E6%95%B0%E7%AD%89%E4%BA%8E%20hash(i)%22%5D%20--%3E%20PAR%5B%22%E5%B9%B6%E8%A1%8C%EF%BC%9A%E5%88%86%E6%AE%B5%E8%AE%A1%E6%95%B0%E5%99%A8%EF%BC%8C%E5%8F%AF%E9%87%8D%E6%94%BE%22%5D%0A%20%20LIN%20--%3E%20TEST%5B%22%E9%AA%8C%E6%94%B6%EF%BC%9ATestU01%20BigCrush%22%5D%0A%20%20PERM%20--%3E%20TEST%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("「通过检验」是必要验收而非保证：BigCrush 覆盖均匀性与线性结构，通过只说明已知攻击面无恙；用在自相关敏感的算法（MCMC、随机化数据结构）上，仍要做应用级验证——同"),e("a",{href:"/cs/condition-number"},"条件数"),a("课的习惯，先问问题对输入的缺陷多敏感。可复现是硬要求：固定算法与种子，序列跨平台一致；各语言标准库的默认生成器互不一致，论文必须写明用的是哪一个。并行流要两件事同时成立：流间不相交，且每条流的统计性质与单流等价；跳进式（一次跳过 \\(2^{64}\\) 步）与计数器分段都行，但线性生成器相邻流可能高度相关——这是 MT 在并行里的实际翻车点，计数器式天生没有这个问题。"),e("span",{class:"marginnote"},"数字实例：跳进式给第 \\(i\\) 个线程的起点是「从种子起跳 \\(i\\times 2^{64}\\) 步」——双精度均匀数取前 53 位时，\\(2^{64}\\) 步对应 \\(2^{11}\\) 个 double，流与流之间隔着两千多个数不会重叠。但「不相交」不等于「独立」：MT 相邻流的向量输出仍可能落在少数超平面上，这正是它在并行里的翻车点。")],-1)),(B(),i(t,null,{default:r(()=>[s(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E5%B9%B6%E8%A1%8C%E6%A8%A1%E6%8B%9F%E8%A6%81%20N%20%E6%9D%A1%E6%B5%81%22%5D%20--%3E%20Q%7B%22%E7%94%9F%E6%88%90%E5%99%A8%E6%98%AF%E5%93%AA%E4%B8%80%E6%97%8F%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%AE%A1%E6%95%B0%E5%99%A8%E5%BC%8F%EF%BC%9APhilox%20%2F%20Threefry%22%7C%20SEG%5B%22%E6%8A%8A%E8%AE%A1%E6%95%B0%E5%99%A8%E5%88%87%E6%AE%B5%3Cbr%2F%3E%E6%B5%81%20i%20%E7%94%A8%E4%B8%80%E6%AE%B5%E4%BA%92%E4%B8%8D%E9%87%8D%E5%8F%A0%E7%9A%84%E8%AE%A1%E6%95%B0%E5%8C%BA%E9%97%B4%22%5D%0A%20%20SEG%20--%3E%20REPLAY%5B%22%E6%AF%8F%E6%9D%A1%E6%B5%81%E5%8F%AF%E5%8D%95%E7%8B%AC%E9%87%8D%E6%94%BE%E4%B8%8E%E7%BB%AD%E7%AE%97%22%5D%0A%20%20Q%20--%3E%7C%22%E7%BA%BF%E6%80%A7%E6%97%8F%EF%BC%9AMT19937%22%7C%20JUMP%5B%22%E5%8F%AA%E8%83%BD%E8%B7%B3%E8%BF%9B%E5%BC%8F%E6%88%96%E5%88%86%E5%9D%97%E5%8F%91%E6%B5%81%22%5D%0A%20%20JUMP%20--%3E%20RISK%5B%22%E7%9B%B8%E9%82%BB%E6%B5%81%E5%8F%AF%E8%83%BD%E9%AB%98%E5%BA%A6%E7%9B%B8%E5%85%B3%3Cbr%2F%3E%E6%A0%B7%E6%9C%AC%E4%BA%92%E7%9B%B8%E6%8A%84%E8%A2%AD%22%5D%0A%20%20REPLAY%20--%3E%20OK%5B%22%E6%B5%81%E9%97%B4%E4%B8%8D%E7%9B%B8%E4%BA%A4%20%2B%20%E5%8D%95%E6%B5%81%E6%80%A7%E8%B4%A8%E4%BF%9D%E6%8C%81%22%5D%0A%20%20RISK%20--%3E%20CHECK%5B%22%E5%BA%94%E7%94%A8%E7%BA%A7%E9%AA%8C%E8%AF%81%EF%BC%9AMCMC%20%E5%B0%A4%E5%85%B6%E8%A6%81%E6%9F%A5%22%5D%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=o('<p>密码学的不可预测性不在此合同内：那要抗状态回溯与熵源攻击，见 <a href="/cs/csprng">CSPRNG</a>。<span class="marginnote">初学者容易把「通过 BigCrush」读成「已被证明随机」，实际上统计检验只能证伪：它像一份体检套餐，查的是已知病种，通过只说明已知项目无异常。MCMC、随机化数据结构这类对自相关敏感的用户，检验之外还得做应用级验证——拿生成器的缺陷直接跑一遍自己的算法看估计量动不动。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲真随机与熵源，不进方差缩减与拟蒙特卡洛——那些在蒙特卡洛方法的应用层；也不写具体常数表与实现细节，选型看验收报告而非传说。后课默认：多起点与扰动实验引用的随机流可命名、可重放，随机性不进入数值误差预算的「不可控」栏目。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生成器是状态转移加输出函数；线性族被格结构与线性检验抓出。</li><li>置换输出（PCG、xoshiro）补线性短板；计数器式（Philox、Threefry）为并行与重放而生。</li><li>整数区间用拒绝采样，直接取模有偏，极端时偏差翻倍。</li><li>科学计算三件套：命名算法、固定种子、分工流；过 BigCrush 只是底线。</li><li>出处：Knuth, TAOCP Vol. 2；Matsumoto and Nishimura, 1998；L&#39;Ecuyer and Simard, 2007；Salmon et al., SC, 2011。</li></ul>',5))])}const f=n(C,[["render",m]]);export{T as __pageData,f as default};
